with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CASE_ID))) as HUB_CLAIM_HK
        , INWARD_NO as BILL_REFERENCE
        , cast(null as varchar) as INVOICE_STATUS
        , 'BJAZ_HAT_OCR_BILL_DETAILS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_ocr_bill_details') }}
    where (nullif(trim(CASE_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , OCR_BILL_NO as BILL_REFERENCE
        , BILL_STATUS as INVOICE_STATUS
        , 'BJAZ_HM_BILL_DETAIL' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_detail') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , OCR_BILL_NO as BILL_REFERENCE
        , BILL_STATUS as INVOICE_STATUS
        , 'BJAZ_HM_BILL_DETAIL_OCR' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_detail_ocr') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BILL_REFERENCE end) as BILL_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INVOICE_STATUS end) as INVOICE_STATUS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when BILL_REFERENCE is not null or INVOICE_STATUS is not null
                     then md5(upper(coalesce(cast(BILL_REFERENCE as varchar), '') || '|' || coalesce(cast(INVOICE_STATUS as varchar), '')))
                end as SAT_CLAIM_BILL_DIGITISATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_BILL_DIGITISATION_HASHDIFF is not null
